arguments.file_text:
@implements IDisposable
@inject INotificationService NotificationService

<button class="notification-badge" @onclick="HandleClick">
    @if (_unreadCount > 0)
    {
        <span class="badge">@_unreadCount</span>
    }
</button>

@code {
    private int _unreadCount;
    private Timer? _pollTimer;

    [Parameter]
    public EventCallback OnClick { get; set; }

    protected override async Task OnInitializedAsync()
    {
        _unreadCount = await NotificationService.GetUnreadCountAsync();
        NotificationService.OnNotificationReceived += HandleNotificationReceived;
        _pollTimer = new Timer(PollUnreadCount, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
    }

    private void HandleNotificationReceived(Notification notification)
    {
        _unreadCount++;
        InvokeAsync(StateHasChanged);
    }

    private async void PollUnreadCount(object? state)
    {
        _unreadCount = await NotificationService.GetUnreadCountAsync();
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleClick()
    {
        await OnClick.InvokeAsync();
    }

    public void Dispose()
    {
        NotificationService.OnNotificationReceived -= HandleNotificationReceived;
        _pollTimer?.Dispose();
    }
}

